import Foundation
import Libbox
import Library
import SwiftUI

@MainActor
public struct HakoNewProfileView: View {
    @EnvironmentObject private var environments: ExtensionEnvironments
    @Environment(\.dismiss) private var dismiss
    @StateObject private var viewModel: NewProfileViewModel
    private var onSuccess: ((Profile) async -> Void)?

    /// The two import requests are the shared view's own types, under the names its callers use.
    ///
    /// # The defect, twice
    ///
    /// The migration renamed these nested types to `HakoImportRequest` / `HakoLocalImportRequest`, which
    /// was a compile error: `NewProfileViewModel.init` takes `NewProfileView.ImportRequest?`, so a copy
    /// under another name does not type-check.
    ///
    /// The first repair aliased them under the **renamed** names - `HakoImportRequest = NewProfileView
    /// .ImportRequest` - which fixed the initialiser and left the other half broken:
    /// `HakoNewProfileMenuView` holds its state as `HakoNewProfileView.ImportRequest?` and constructs
    /// `HakoNewProfileView.ImportRequest(name:url:)` at four sites. Those members did not exist. An alias
    /// only helps if it wears the name its callers already spell.
    ///
    /// So the aliases now use the **original** names, and both sides agree:
    ///
    ///     HakoNewProfileMenuView:  HakoNewProfileView.ImportRequest   -> resolves
    ///     the initialiser:         ImportRequest                      -> is NewProfileView.ImportRequest
    ///     the view model:          NewProfileView.ImportRequest       -> the same type
    ///
    /// Re-declaring the types was never necessary. They are nested, so they cannot collide with a
    /// module-scope name, and nothing outside the shared view constructs them - the menu only ever holds
    /// and passes one.
    public typealias ImportRequest = NewProfileView.ImportRequest
    public typealias LocalImportRequest = NewProfileView.LocalImportRequest

    public init(
        _ importRequest: ImportRequest? = nil,
        localImportRequest: LocalImportRequest? = nil,
        onSuccess: ((Profile) async -> Void)? = nil
    ) {
        _viewModel = StateObject(wrappedValue: NewProfileViewModel(importRequest: importRequest, localImportRequest: localImportRequest))
        self.onSuccess = onSuccess
    }

    public var body: some View {


            iOSBody

    }

    private static var profileTypeOptions: [FormPickerOption<ProfileType>] {
        var options = [FormPickerOption(ProfileType.local, String(localized: "Local"))]

            options.append(FormPickerOption(ProfileType.icloud, String(localized: "iCloud")))

        options.append(FormPickerOption(ProfileType.remote, String(localized: "Remote")))
        return options
    }

    private static var fileImportOptions: [FormPickerOption<Bool>] {
        [
            FormPickerOption(false, String(localized: "Create New")),
            FormPickerOption(true, String(localized: "Import")),
        ]
    }

    private var ownsDismiss: Bool {


            true

    }

    private var formContent: some View {
        FormView {
            Section {
                FormItem(String(localized: "Name")) {
                    TextField("Name", text: $viewModel.profileName, prompt: Text("Required"))
                        .multilineTextAlignment(.trailing)
                }
                FormPicker(String(localized: "Type"), options: Self.profileTypeOptions, selection: $viewModel.profileType)
                if viewModel.profileType == .local {
                    FormPicker(String(localized: "File"), options: Self.fileImportOptions, selection: $viewModel.fileImport)


                    Group {
                        if viewModel.fileImport {
                            HStack {
                                Text("File Path")
                                Spacer()
                                Spacer()
                                if let fileURL = viewModel.fileURL {
                                    Button(fileURL.fileName) {
                                        viewModel.pickerPresented = true
                                    }
                                } else {
                                    Button("Choose") {
                                        viewModel.pickerPresented = true
                                    }
                                }
                            }
                        }
                    }
                } else if viewModel.profileType == .icloud {
                    FormItem(String(localized: "Path")) {
                        TextField("Path", text: $viewModel.remotePath, prompt: Text("Required"))
                            .multilineTextAlignment(.trailing)
                    }
                } else if viewModel.profileType == .remote {
                    FormItem(String(localized: "URL")) {
                        TextField("URL", text: $viewModel.remotePath, prompt: Text("Required"))
                            .multilineTextAlignment(.trailing)

                            #if !os(macOS)
                            .keyboardType(.URL)
                            #endif

                    }
                    Toggle("Auto Update", isOn: $viewModel.autoUpdate)
                    FormItem(String(localized: "Auto Update Interval")) {
                        TextField("Auto Update Interval", text: $viewModel.autoUpdateInterval.stringBinding(defaultValue: 60), prompt: Text("In Minutes"))
                            .multilineTextAlignment(.trailing)

                            #if !os(macOS)
                            .keyboardType(.numberPad)
                            #endif

                    }
                }
            } footer: {
                if viewModel.profileType == .icloud {
                    let fileName = viewModel.remotePath.isEmpty ? String(localized: "FileName") : viewModel.remotePath
                    Text("File will be located at iCloud Drive/sing-box/\(fileName)")
                }
            }

                // No card: the review asked for the primary button to sit on the page's own
                // background rather than inside a white row that exists only to hold it.
                Section {
                    if !viewModel.isSaving {
                        FormButton {
                            viewModel.isSaving = true
                            Task {
                                await viewModel.createProfile(
                                    environments: environments,
                                    dismiss: ownsDismiss ? dismiss : nil,
                                    onSuccess: onSuccess
                                )
                            }
                        } label: {
                            // The title centred in the button, the glyph beside it rather than in
                            // front of it: a `Label` centres glyph and text as one unit, which
                            // puts the words right of the button's centre - the review's "the
                            // Create text must be truly centred in the clickable area".
                            Text("Create")
                                .frame(maxWidth: .infinity)
                                .overlay(alignment: .leading) {
                                    Image(systemName: "doc.fill.badge.plus")
                                }
                        }
                        // The page's primary action, in the design system's primary treatment.
                        // `FormButton` is a bare button on the touch platforms, so this was a
                        // blue text row while every other primary action in the client is a
                        // filled one - the review's "the Create button must use the global
                        // primary style".
                        .hakoPrimaryActionButtonStyle()
                        .controlSize(.large)
                        .listRowBackground(Color.clear)
                        .listRowInsets(EdgeInsets())
                    } else {
                        ProgressView()
                            .listRowBackground(Color.clear)
                    }
                }

        }
    }


        private var iOSBody: some View {
            formContent
                .disabled(viewModel.isSaving)
                .alert($viewModel.alert)
                .onChangeCompat(of: viewModel.createSucceeded) { newValue in
                    if newValue, ownsDismiss {
                        dismiss()
                    }
                }

                .fileImporter(
                    isPresented: $viewModel.pickerPresented,
                    allowedContentTypes: [.json],
                    allowsMultipleSelection: false
                ) { result in
                    do {
                        let urls = try result.get()
                        if !urls.isEmpty {
                            viewModel.fileURL = urls[0]
                        }
                    } catch {
                        viewModel.alert = AlertState(action: "read imported profile file", error: error)
                        return
                    }
                }

        }

}
